251→// UninstallHooks removes Entire hooks from Claude Code settings.
252→func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
253→	// Use repo root to find .claude directory when run from a subdirectory
254→	repoRoot, err := paths.WorktreeRoot(ctx)
255→	if err != nil {
256→		repoRoot = "." // Fallback to CWD if not in a git repo
257→	}
258→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
259→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
260→	if err != nil {
261→		return nil //nolint:nilerr // No settings file means nothing to uninstall
262→	}
263→
264→	var rawSettings map[string]json.RawMessage
265→	if err := json.Unmarshal(data, &rawSettings); err != nil {
266→		return fmt.Errorf("failed to parse settings.json: %w", err)
267→	}
268→
269→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
270→	var rawHooks map[string]json.RawMessage
271→	if hooksRaw, ok := rawSettings["hooks"]; ok {
272→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
273→			return fmt.Errorf("failed to parse hooks: %w", err)
274→		}
275→	}
276→	if rawHooks == nil {
277→		rawHooks = make(map[string]json.RawMessage)
278→	}
279→
280→	// Parse only the hook types we need to modify
281→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
282→	parseHookType(rawHooks, "SessionStart", &sessionStart)
283→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
284→	parseHookType(rawHooks, "Stop", &stop)
285→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
286→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
287→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
288→
289→	// Remove Entire hooks from all hook types
290→	sessionStart = removeEntireHooks(sessionStart)
291→	sessionEnd = removeEntireHooks(sessionEnd)
292→	stop = removeEntireHooks(stop)
293→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
294→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
295→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
296→
297→	// Marshal modified hook types back to rawHooks
298→	marshalHookType(rawHooks, "SessionStart", sessionStart)
299→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
300→	marshalHookType(rawHooks, "Stop", stop)
301→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
302→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
303→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
304→
305→	// Also remove the metadata deny rule from permissions
306→	var rawPermissions map[string]json.RawMessage
307→	if permRaw, ok := rawSettings["permissions"]; ok {
308→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
309→			// If parsing fails, just skip permissions cleanup
310→			rawPermissions = nil
311→		}
312→	}
313→
314→	if rawPermissions != nil {
315→		if denyRaw, ok := rawPermissions["deny"]; ok {
316→			var denyRules []string
317→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
318→				// Filter out the metadata deny rule
319→				filteredRules := make([]string, 0, len(denyRules))
320→				for _, rule := range denyRules {
321→					if rule != metadataDenyRule {
322→						filteredRules = append(filteredRules, rule)
323→					}
324→				}
325→				if len(filteredRules) > 0 {
326→					denyJSON, err := json.Marshal(filteredRules)
327→					if err == nil {
328→						rawPermissions["deny"] = denyJSON
329→					}
330→				} else {
331→					// Remove empty deny array
332→					delete(rawPermissions, "deny")
333→				}
334→			}
335→		}
336→
337→		// If permissions is empty, remove it entirely
338→		if len(rawPermissions) > 0 {
339→			permJSON, err := json.Marshal(rawPermissions)
340→			if err == nil {
341→				rawSettings["permissions"] = permJSON
342→			}
343→		} else {
344→			delete(rawSettings, "permissions")
345→		}
346→	}
347→
348→	// Marshal hooks back (preserving unknown hook types)
349→	if len(rawHooks) > 0 {
350→		hooksJSON, err := json.Marshal(rawHooks)
351→		if err != nil {
352→			return fmt.Errorf("failed to marshal hooks: %w", err)
353→		}
354→		rawSettings["hooks"] = hooksJSON
355→	} else {
356→		delete(rawSettings, "hooks")
357→	}
358→
359→	// Write back
360→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
361→	if err != nil {
362→		return fmt.Errorf("failed to marshal settings: %w", err)
363→	}
364→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
365→		return fmt.Errorf("failed to write settings.json: %w", err)
366→	}
367→	return nil
368→}
369→
370→// AreHooksInstalled checks if Entire hooks are installed.
371→func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
372→	// Use repo root to find .claude directory when run from a subdirectory
373→	repoRoot, err := paths.WorktreeRoot(ctx)
374→	if err != nil {
375→		repoRoot = "." // Fallback to CWD if not in a git repo
376→	}
377→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
378→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
379→	if err != nil {
380→		return false
381→	}
382→
383→	var settings ClaudeSettings
384→	if err := json.Unmarshal(data, &settings); err != nil {
385→		return false
386→	}
387→
388→	// Check for at least one of our hooks (new or old format)
389→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
390→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
391→		// Backwards compatibility: check for old hook formats
392→		hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
393→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
394→		hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
395→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
396→}
397→
398→// Helper functions for hook management
399→
400→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
401→	for _, matcher := range matchers {
402→		for _, hook := range matcher.Hooks {
403→			if hook.Command == command {
404→				return true
405→			}
406→		}
407→	}
408→	return false
409→}
410→
411→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
412→	for _, matcher := range matchers {
413→		if matcher.Matcher == matcherName {
414→			for _, hook := range matcher.Hooks {
415→				if hook.Command == command {
416→					return true
417→				}
418→			}
419→		}
420→	}
421→	return false
422→}
423→
424→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
425→	entry := ClaudeHookEntry{
426→		Type:    "command",
427→		Command: command,
428→	}
429→
430→	// If no matcher name, add to a matcher with empty string
431→	if matcherName == "" {
432→		for i, matcher := range matchers {
433→			if matcher.Matcher == "" {
434→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
435→				return matchers
436→			}
437→		}
438→		return append(matchers, ClaudeHookMatcher{
439→			Matcher: "",
440→			Hooks:   []ClaudeHookEntry{entry},
441→		})
442→	}
443→
444→	// Find or create matcher with the given name
445→	for i, matcher := range matchers {
446→		if matcher.Matcher == matcherName {
447→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
448→			return matchers
449→		}
450→	}
451→
452→	return append(matchers, ClaudeHookMatcher{
453→		Matcher: matcherName,
454→		Hooks:   []ClaudeHookEntry{entry},
455→	})
456→}
457→
458→// isEntireHook checks if a command is an Entire hook (old or new format)
459→func isEntireHook(command string) bool {
460→	for _, prefix := range entireHookPrefixes {
461→		if strings.HasPrefix(command, prefix) {
462→			return true
463→		}
464→	}
465→	return false
466→}
467→
468→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
469→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
470→	result := make([]ClaudeHookMatcher, 0, len(matchers))
471→	for _, matcher := range matchers {
472→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
473→		for _, hook := range matcher.Hooks {
474→			if !isEntireHook(hook.Command) {
475→				filteredHooks = append(filteredHooks, hook)
476→			}
477→		}
478→		// Only keep the matcher if it has hooks remaining
479→		if len(filteredHooks) > 0 {
480→			matcher.Hooks = filteredHooks
481→			result = append(result, matcher)
482→		}
483→	}
484→	return result
485→}
486→
487→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
488→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
489→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
490→	// Same logic as removeEntireHooks - both work on the same structure
491→	return removeEntireHooks(matchers)
492→}
